from pycompss.api.task import task
from pycompss.api.api import compss_wait_on
from pycompss.api.parameter import *

@task(returns=1)
def operate_row(alpha, beta, A_row, x, y_val):
    dot_product = 0.0
    for a in A_row:
        dot_product += a['value'] * x[a['column']]
    return alpha * dot_product + beta * y_val

def main(alpha, beta, A, x, y):
    N = len(x)
    M = len(y)

    A_by_row = {i: [] for i in range(M)}
    for a in A:
        A_by_row[a['row']].append(a)

    futures = []
    for i in range(M):
        futures.append(operate_row(alpha, beta, A_by_row[i], x, y[i]))

    z = compss_wait_on(futures)

    return z
